@Component("workSchedule-handler")
@ProcessingGroup("workSchedule-processing-group")
public class WorkScheduleEventHandler {
	
	// core constructor
	WorkScheduleEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateWorkScheduleEvent
     */
    @EventHandler
    public void handle( CreateWorkScheduleEvent event) {
        entityManager.persist(new WorkSchedule(event.getWorkScheduleId(), event.getName(), event.getStandardHoursPerWeek(), event.getContracts(), event.getShifts(), event.getExceptions(), event.getScheduleType()));
    }

    /*
     * @param	event UpdateWorkScheduleEvent
     */
    @EventHandler
    public WorkSchedule handle( UpdateWorkScheduleEvent event) {
    	entityManager.merge(new WorkSchedule(event.getWorkScheduleId(), event.getName(), event.getStandardHoursPerWeek(), event.getContracts(), event.getShifts(), event.getExceptions(), event.getScheduleType()));
    }
    
    /*
     * @param	event DeleteWorkScheduleEvent
     */
    @EventHandler
    public void on( DeleteWorkScheduleEvent event) {
    	WorkSchedule entity = new WorkSchedule();
   
    	// ------------------------------------------
    	// apply the WorkScheduleId
    	// ------------------------------------------
    	entity.setWorkScheduleId( event.getWorkScheduleId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final WorkScheduleRepository workScheduleEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(WorkScheduleEventHandler.class.getName());

}
